package cn.zhuatech.aps.controller; import cn.zhuatech.aps.common.ApiResponse; import cn.zhuatech.aps.dto.ApsDto.*; import cn.zhuatech.aps.service.ApsService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public class ShopfloorController {private final ApsService aps;public ShopfloorController(ApsService aps){this.aps=aps;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(aps.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",aps.report(id,request));}}
